  create policy "Friends can read course colors"
  on "public"."course_colors"
  as permissive
  for select
  to authenticated
using (public.are_friends(( SELECT auth.uid() AS uid), "user"));



  create policy "Friends can read events"
  on "public"."events"
  as permissive
  for select
  to authenticated
using (public.are_friends(( SELECT auth.uid() AS uid), "user"));



  create policy "Addressee can accept"
  on "public"."friendships"
  as permissive
  for update
  to authenticated
using (((( SELECT auth.uid() AS uid) = addressee) AND (status = 'pending'::public.friendship_status)))
with check (((( SELECT auth.uid() AS uid) = addressee) AND (status = 'accepted'::public.friendship_status)));



  create policy "Either party can remove"
  on "public"."friendships"
  as permissive
  for delete
  to authenticated
using (((( SELECT auth.uid() AS uid) = requester) OR (( SELECT auth.uid() AS uid) = addressee)));



  create policy "Users can read own friendships"
  on "public"."friendships"
  as permissive
  for select
  to authenticated
using (((( SELECT auth.uid() AS uid) = requester) OR (( SELECT auth.uid() AS uid) = addressee)));



  create policy "Users can send friend requests"
  on "public"."friendships"
  as permissive
  for insert
  to authenticated
with check (((( SELECT auth.uid() AS uid) = requester) AND (status = 'pending'::public.friendship_status)));



  create policy "Authenticated users can read profiles"
  on "public"."users"
  as permissive
  for select
  to authenticated
using (true);



